package com.jbrempresa.backend.entity;
import java.time.LocalDateTime; import com.fasterxml.jackson.annotation.JsonFormat; import jakarta.persistence.*;
@Entity @Table(name="municipios") public class Municipio {
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) @Column(name="mun_id") private Long munId; @Column(name="emp_id",nullable=false) private Long empId; @Column(name="prv_id",nullable=false) private Long prvId; @Column(name="mun_cod",nullable=false,length=20) private String munCod; @Column(name="mun_nom",nullable=false,length=100) private String munNom; @Column(name="mun_usu_mov",nullable=false,length=50) private String munUsuMov; @JsonFormat(pattern="dd/MM/yyyy HH:mm:ss") @Column(name="mun_fec_mov",nullable=false) private LocalDateTime munFecMov; @Column(name="mun_act",nullable=false) private Boolean munAct;
 public Long getMunId(){return munId;} public void setMunId(Long v){munId=v;} public Long getEmpId(){return empId;} public void setEmpId(Long v){empId=v;} public Long getPrvId(){return prvId;} public void setPrvId(Long v){prvId=v;} public String getMunCod(){return munCod;} public void setMunCod(String v){munCod=v;} public String getMunNom(){return munNom;} public void setMunNom(String v){munNom=v;} public String getMunUsuMov(){return munUsuMov;} public void setMunUsuMov(String v){munUsuMov=v;} public LocalDateTime getMunFecMov(){return munFecMov;} public void setMunFecMov(LocalDateTime v){munFecMov=v;} public Boolean getMunAct(){return munAct;} public void setMunAct(Boolean v){munAct=v;}
}
